enum class V100Tab(val label:String){Home("Acasă"),Categories("Categorii"),Ai("AI Assistant"),Cart("Coș"),Account("Contul meu")}

@Composable
fun AutoIdAppV100(api:AutoIdApi,session:SessionStore,commerce:CommerceStore,scan:((String)->Unit)->Unit){
    var ready by remember{mutableStateOf(false)};LaunchedEffect(Unit){delay(1800);ready=true};if(!ready){LoadingScreenV100();return}
    var tab by remember{mutableStateOf(V100Tab.Home)};var category by remember{mutableStateOf<ProductCategory?>(null)};var selected by remember{mutableStateOf<Product?>(null)};var search by remember{mutableStateOf("")};var menu by remember{mutableStateOf(false)};var favorites by remember{mutableStateOf(false)};var notifications by remember{mutableStateOf(false)};var checkout by remember{mutableStateOf(false)};var ai by remember{mutableStateOf(false)};var consult by remember{mutableStateOf(false)};var rfq by remember{mutableStateOf(false)};var rfqLines by remember{mutableStateOf<List<CartLine>>(emptyList())};var miniCart by remember{mutableStateOf(false)};var cartTick by remember{mutableIntStateOf(0)};var favTick by remember{mutableIntStateOf(0)}
    fun addCart(p:Product,q:Int=1){commerce.addToCart(p,q);cartTick++;miniCart=true}
    fun addRfq(p:Product,q:Int=1){val x=rfqLines.toMutableList();val i=x.indexOfFirst{it.product.id==p.id};if(i>=0)x[i]=x[i].copy(quantity=x[i].quantity+q) else x+=CartLine(p,q);rfqLines=x;rfq=true}
    fun openProduct(p:Product){commerce.addRecent(p);selected=p;category=null;favorites=false}
    fun openCategory(c:ProductCategory){category=c;selected=null;tab=V100Tab.Categories}
    if(checkout){CheckoutV08(api,commerce,onBack={checkout=false},onDone={commerce.clearCart();cartTick++;checkout=false;tab=V100Tab.Account});return}
    if(ai){NativeAiChatScreen(api,null){ai=false};return}
    val drawer=rememberDrawerState(DrawerValue.Closed);LaunchedEffect(menu){if(menu)drawer.open() else drawer.close()}
    ModalNavigationDrawer(drawerState=drawer,gesturesEnabled=menu,drawerContent={V100Menu(api,{menu=false},{menu=false;tab=V100Tab.Home;category=null;selected=null},{menu=false;openCategory(it)},{menu=false;favorites=true},{menu=false;notifications=true},{menu=false;consult=true},{menu=false;ai=true})}){
        Scaffold(containerColor=Color.White,bottomBar={V100Bottom(tab,commerce.cartCount()){t->if(t==V100Tab.Ai)ai=true else{tab=t;selected=null;if(t!=V100Tab.Categories)category=null;favorites=false;notifications=false}}}){pad->Box(Modifier.padding(pad).fillMaxSize()){
            when{
                favorites->FavoritesV100(api,commerce,{favorites=false},::openProduct,{tab=V100Tab.Cart;favorites=false})
                notifications->NotificationsV100({notifications=false},{tab=V100Tab.Cart;notifications=false})
                selected!=null->ProductV100(selected!!,api,commerce,{selected=null},{commerce.toggleFavorite(it.id);favTick++},{p,q->addCart(p,q)},{p,q->addRfq(p,q)},::openProduct,{ai=true},{tab=V100Tab.Cart;selected=null})
                category!=null->CatalogV100(api,commerce,category,search,{category=null},::openProduct,{commerce.toggleFavorite(it.id);favTick++},{addCart(it)},{addRfq(it)},{ai=true},{favorites=true},{tab=V100Tab.Cart;category=null},scan)
                else->when(tab){
                    V100Tab.Home->HomeV100(api,commerce,{menu=true},{search=it;category=ProductCategory(0,"Rezultate",0)},::openCategory,::openProduct,{commerce.toggleFavorite(it.id);favTick++},{addCart(it)},{ai=true},{consult=true},{favorites=true},{notifications=true},{tab=V100Tab.Cart},miniCart,{miniCart=it},scan,cartTick)
                    V100Tab.Categories->CatalogV100(api,commerce,null,search,{tab=V100Tab.Home},::openProduct,{commerce.toggleFavorite(it.id);favTick++},{addCart(it)},{addRfq(it)},{ai=true},{favorites=true},{tab=V100Tab.Cart},scan)
                    V100Tab.Cart->CartV100(commerce,::openProduct,{cartTick++},{checkout=true})
                    V100Tab.Account->AccountScreenV08(api,session,commerce,::openProduct){tab=V100Tab.Cart}
                    V100Tab.Ai->{}
                }
            }
        }}
    }
    if(rfq)RfqV100(api,rfqLines,{rfqLines=it},{rfq=false},{rfqLines=emptyList();rfq=false})
    if(consult)ConsultV100(api){consult=false}
}

@Composable private fun LoadingScreenV100(){Box(Modifier.fillMaxSize().background(Color.White).statusBarsPadding(),contentAlignment=Alignment.Center){Column(horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.spacedBy(14.dp)){Image(painterResource(R.drawable.autoid_logo_transparent),"AutoID",Modifier.width(270.dp).height(90.dp),contentScale=ContentScale.Fit);Text("Bine ai venit!",fontSize=25.sp,fontWeight=FontWeight.ExtraBold,color=Ink);Text("Soluții profesionale pentru identificare automată",color=Muted);Spacer(Modifier.height(8.dp));LinearProgressIndicator(Modifier.width(210.dp),color=AutoIdOrange,trackColor=Color(0xFFF2F4F7));Text("Se încarcă experiența AutoID...",fontSize=12.sp,color=Muted)}}}

@Composable private fun V100Bottom(tab:V100Tab,count:Int,onTab:(V100Tab)->Unit){NavigationBar(containerColor=Color.White,tonalElevation=10.dp,modifier=Modifier.navigationBarsPadding()){V100Tab.entries.forEach{item->NavigationBarItem(selected=tab==item,onClick={onTab(item)},icon={if(item==V100Tab.Ai)Surface(shape=CircleShape,color=AutoIdOrange,shadowElevation=5.dp,modifier=Modifier.size(48.dp)){Box(contentAlignment=Alignment.Center){Icon(Icons.Default.SmartToy,"AI",tint=Color.White)}} else BadgedBox(badge={if(item==V100Tab.Cart&&count>0)Badge(containerColor=AutoIdOrange){Text(count.toString())}}){Icon(when(item){V100Tab.Home->Icons.Default.Home;V100Tab.Categories->Icons.Default.GridView;V100Tab.Cart->Icons.Default.ShoppingCart;V100Tab.Account->Icons.Default.Person;else->Icons.Default.SmartToy},item.label)}},label={Text(if(item==V100Tab.Ai)"AI" else item.label,fontSize=10.sp)},colors=NavigationBarItemDefaults.colors(selectedIconColor=AutoIdOrange,selectedTextColor=AutoIdOrange,indicatorColor=Color(0xFFFFF1E8)))}}}

