@Composable private fun HomeHeader(commerce:CommerceStore,onMenu:()->Unit,onFav:()->Unit,onNotif:()->Unit,onCart:()->Unit,mini:Boolean,onMini:(Boolean)->Unit,tick:Int){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){IconButton(onClick=onMenu){Icon(Icons.Default.Menu,"Meniu",Modifier.size(28.dp))};Spacer(Modifier.weight(1f));Image(painterResource(R.drawable.autoid_logo_transparent),"AutoID",Modifier.width(160.dp).height(54.dp),contentScale=ContentScale.Fit);Spacer(Modifier.weight(1f));IconButton(onClick=onFav){Icon(Icons.Default.FavoriteBorder,"Favorite")};IconButton(onClick=onNotif){BadgedBox(badge={Badge(containerColor=AutoIdOrange){Text("3")}}){Icon(Icons.Default.NotificationsNone,"Notificări")}};Box{IconButton(onClick={onMini(!mini)}){BadgedBox(badge={if(commerce.cartCount()>0)Badge(containerColor=AutoIdOrange){Text(commerce.cartCount().toString())}}){Icon(Icons.Default.ShoppingCart,"Coș")}};MiniCart(commerce,mini,{onMini(false)},onCart,tick)}}}
@Composable private fun MiniCart(commerce:CommerceStore,open:Boolean,onDismiss:()->Unit,onCart:()->Unit,tick:Int){DropdownMenu(expanded=open,onDismissRequest=onDismiss,modifier=Modifier.width(330.dp).background(Color.White)){val lines=commerce.cart();Row(Modifier.fillMaxWidth().padding(horizontal=14.dp,vertical=8.dp),verticalAlignment=Alignment.CenterVertically){Text("Coșul meu (${commerce.cartCount()})",fontWeight=FontWeight.ExtraBold,modifier=Modifier.weight(1f));TextButton(onClick={commerce.clearCart();onDismiss()}){Text("Șterge")}};HorizontalDivider();if(lines.isEmpty())DropdownMenuItem(text={Text("Coșul este gol",color=Muted)},onClick={}) else lines.take(4).forEach{l->DropdownMenuItem(text={Row(verticalAlignment=Alignment.CenterVertically){AsyncImage(l.product.imageUrl,l.product.name,Modifier.size(46.dp));Spacer(Modifier.width(8.dp));Column(Modifier.weight(1f)){Text(l.product.name,maxLines=1,overflow=TextOverflow.Ellipsis,fontWeight=FontWeight.SemiBold);Text("${l.quantity} × ${l.product.currentInclVat.ifBlank{l.product.price}}",fontSize=11.sp,color=Muted)}}},onClick={})};if(lines.isNotEmpty()){HorizontalDivider();Button(onClick={onDismiss();onCart()},modifier=Modifier.fillMaxWidth().padding(12.dp)){Text("Vezi coșul")}}}}

@Composable private fun SmartSearch(api:AutoIdApi,value:String,onValue:(String)->Unit,onSubmit:(String)->Unit,scan:((String)->Unit)->Unit,placeholder:String="Caută produse, SKU, brand, model..."){var suggestions by remember{mutableStateOf<List<Product>>(emptyList())};var busy by remember{mutableStateOf(false)};LaunchedEffect(value){delay(260);if(value.trim().length>=2){busy=true;suggestions=runCatching{withContext(Dispatchers.IO){api.searchSuggestions(value.trim())}}.getOrDefault(emptyList());busy=false}else suggestions=emptyList()};Column{OutlinedTextField(value,onValue,modifier=Modifier.fillMaxWidth(),singleLine=true,placeholder={Text(placeholder)},leadingIcon={Icon(Icons.Default.Search,null)},trailingIcon={Row{if(busy)CircularProgressIndicator(Modifier.size(18.dp),strokeWidth=2.dp);IconButton(onClick={scan{onValue(it);onSubmit(it)}}){Icon(Icons.Default.QrCodeScanner,"Scanner")}}},shape=RoundedCornerShape(16.dp));AnimatedVisibility(suggestions.isNotEmpty()){ElevatedCard(Modifier.fillMaxWidth().padding(top=4.dp),shape=RoundedCornerShape(14.dp)){Column{suggestions.take(5).forEach{p->Row(Modifier.fillMaxWidth().clickable{onValue("");onSubmit(p.sku.ifBlank{p.name})}.padding(10.dp),verticalAlignment=Alignment.CenterVertically){AsyncImage(p.imageUrl,p.name,Modifier.size(42.dp));Spacer(Modifier.width(8.dp));Column(Modifier.weight(1f)){Text(p.name,maxLines=1,overflow=TextOverflow.Ellipsis,fontWeight=FontWeight.SemiBold);Text(listOf(p.sku,p.brand,p.model).filter{it.isNotBlank()}.joinToString(" · "),fontSize=11.sp,color=Muted)}};HorizontalDivider()}}}}}}

@Composable fun HomeV100(api:AutoIdApi,commerce:CommerceStore,onMenu:()->Unit,onSearch:(String)->Unit,onCategory:(ProductCategory)->Unit,onProduct:(Product)->Unit,onFavorite:(Product)->Unit,onCart:(Product)->Unit,onAi:()->Unit,onConsult:()->Unit,onFavorites:()->Unit,onNotifications:()->Unit,onFullCart:()->Unit,mini:Boolean,onMini:(Boolean)->Unit,scan:((String)->Unit)->Unit,cartTick:Int){var q by remember{mutableStateOf("")};var data by remember{mutableStateOf<HomeV100Data?>(null)};var loading by remember{mutableStateOf(true)};var error by remember{mutableStateOf<String?>(null)};LaunchedEffect(Unit){runCatching{withContext(Dispatchers.IO){api.homeData()}}.onSuccess{data=it}.onFailure{error=it.message};loading=false};LazyColumn(Modifier.fillMaxSize().padding(horizontal=16.dp).statusBarsPadding(),verticalArrangement=Arrangement.spacedBy(20.dp),contentPadding=PaddingValues(bottom=24.dp)){item{HomeHeader(commerce,onMenu,onFavorites,onNotifications,onFullCart,mini,onMini,cartTick);SmartSearch(api,q,{q=it},{onSearch(it)},scan)};item{Hero(data?.recommended?.firstOrNull(),{data?.categories?.firstOrNull()?.let(onCategory)},onAi)};item{SectionHead("Categorii rapide","Vezi toate"){};LazyRow(horizontalArrangement=Arrangement.spacedBy(14.dp),contentPadding=PaddingValues(vertical=4.dp)){items((data?.sections?:emptyList()).take(8)){s->QuickCategory(s.category,onCategory)}}};item{AiCard(onAi)};if(loading)item{LinearProgressIndicator(Modifier.fillMaxWidth(),color=AutoIdOrange)};error?.let{item{Text(it,color=MaterialTheme.colorScheme.error)}};val rec=data?.recommended?:emptyList();if(rec.isNotEmpty())item{SectionHead("În stoc AutoID","Vezi toate"){};LazyRow(horizontalArrangement=Arrangement.spacedBy(12.dp)){items(rec,key={it.id}){p->HomeCard(p,commerce.isFavorite(p.id),{onProduct(p)},{onFavorite(p)},{onCart(p)})}}};val offers=data?.offers?:emptyList();if(offers.isNotEmpty())item{SectionHead("Oferte speciale","Vezi toate"){};LazyRow(horizontalArrangement=Arrangement.spacedBy(12.dp)){items(offers,key={it.id}){p->HomeCard(p,commerce.isFavorite(p.id),{onProduct(p)},{onFavorite(p)},{onCart(p)})}}};item{ConsultCard(onConsult)}}}

