@Composable private fun HomeCard(p:Product,favorite:Boolean,onClick:()->Unit,onFavorite:()->Unit,onCart:()->Unit){ElevatedCard(Modifier.width(188.dp),shape=RoundedCornerShape(18.dp)){Column(Modifier.clickable(onClick=onClick).padding(12.dp)){Box(Modifier.fillMaxWidth().height(118.dp)){AsyncImage(p.imageUrl,p.name,Modifier.fillMaxSize(),contentScale=ContentScale.Fit);IconButton(onClick=onFavorite,modifier=Modifier.align(Alignment.TopEnd)){Icon(if(favorite)Icons.Default.Favorite else Icons.Default.FavoriteBorder,"Favorite",tint=if(favorite)AutoIdOrange else Ink)};DiscountChip(p,Modifier.align(Alignment.TopStart))};Text(p.brand.ifBlank{p.category},fontSize=11.sp,color=Muted);Text(p.name,maxLines=2,overflow=TextOverflow.Ellipsis,fontWeight=FontWeight.Bold);Spacer(Modifier.height(4.dp));CompactPrice(p);Spacer(Modifier.height(5.dp));StockLine(p,true);if(!isGrouped(p))IconButton(onClick=onCart,modifier=Modifier.align(Alignment.End)){Icon(Icons.Default.AddShoppingCart,"Adaugă",tint=AutoIdOrange)}}}}
@Composable private fun DiscountChip(p:Product,modifier:Modifier=Modifier){val d=discount(p);if(d>0)Surface(modifier=modifier,shape=RoundedCornerShape(50),color=Good){Text("-$d%",Modifier.padding(horizontal=8.dp,vertical=4.dp),color=Color.White,fontSize=11.sp,fontWeight=FontWeight.Bold)}}
private fun discount(p:Product):Int=if(p.msrpEuroValue>0&&p.autoIdEuroValue>0&&p.msrpEuroValue>p.autoIdEuroValue)(((p.msrpEuroValue-p.autoIdEuroValue)/p.msrpEuroValue)*100).roundToInt().coerceAtLeast(1) else 0
private fun isGrouped(p:Product)=p.productType=="grouped"||p.groupedChildIds.isNotEmpty()
@Composable private fun CompactPrice(p:Product){Text(if(isGrouped(p))"de la ${p.priceRangeInclVat.ifBlank{p.currentInclVat.ifBlank{p.price}}}" else p.currentInclVat.ifBlank{p.price},fontWeight=FontWeight.ExtraBold,fontSize=14.sp,color=Ink)}
@Composable private fun StockLine(p:Product,compact:Boolean=false){val a=if(isGrouped(p))p.groupedStockAutoId?:0 else p.stockAutoId?:0;val d=if(isGrouped(p))p.groupedStockDistributor?:0 else p.stockDistributor?:0;Row(horizontalArrangement=Arrangement.spacedBy(6.dp),verticalAlignment=Alignment.CenterVertically){if(a>0){Box(Modifier.size(if(compact)7.dp else 9.dp).background(Good,CircleShape));Text("$a în stoc",fontSize=if(compact)10.sp else 12.sp,color=Color(0xFF067647),fontWeight=FontWeight.Bold)};if(d>0){Box(Modifier.size(if(compact)7.dp else 9.dp).background(Warn,CircleShape));Text("$d livrare 5–7 zile",fontSize=if(compact)10.sp else 12.sp,color=Color(0xFFB54708),fontWeight=FontWeight.Bold)};if(a<=0&&d<=0)Text("Cere ofertă pentru disponibilitate",fontSize=if(compact)10.sp else 12.sp,color=Muted,fontWeight=FontWeight.Bold)}}

@Composable fun CatalogV100(api:AutoIdApi,commerce:CommerceStore,category:ProductCategory?,initialSearch:String,onBack:()->Unit,onProduct:(Product)->Unit,onFavorite:(Product)->Unit,onCart:(Product)->Unit,onRfq:(Product)->Unit,onAi:()->Unit,onFavorites:()->Unit,onHeaderCart:()->Unit,scan:((String)->Unit)->Unit){var q by remember(category?.id){mutableStateOf(initialSearch)};var products by remember{mutableStateOf<List<Product>>(emptyList())};var facets by remember{mutableStateOf<CatalogFacets?>(null)};var active by remember(category?.id){mutableStateOf(category)};var brand by remember{mutableStateOf<Long?>(null)};var model by remember{mutableStateOf<Long?>(null)};var min by remember{mutableStateOf<Double?>(null)};var max by remember{mutableStateOf<Double?>(null)};var sort by remember{mutableStateOf("stock_autoid")};var page by remember{mutableIntStateOf(1)};var loading by remember{mutableStateOf(false)};var filters by remember{mutableStateOf(false)};var error by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();suspend fun load(reset:Boolean){loading=true;error=null;if(reset)page=1;val rows=runCatching{withContext(Dispatchers.IO){api.catalogProducts(q,active?.id,page,sort,brand,model,min,max)}}.onFailure{error=it.message}.getOrDefault(emptyList());products=if(reset)rows else products+rows;loading=false};LaunchedEffect(category?.id){facets=runCatching{withContext(Dispatchers.IO){api.catalogFacets(category?.id)}}.getOrNull()};LaunchedEffect(active?.id,brand,model,min,max,sort){load(true)};LaunchedEffect(q){delay(350);load(true)};Column(Modifier.fillMaxSize().padding(horizontal=14.dp).statusBarsPadding()){Row(verticalAlignment=Alignment.CenterVertically){IconButton(onClick=onBack){Icon(Icons.Default.ArrowBack,"Înapoi")};Text(category?.name?:"Categorii produse",fontSize=20.sp,fontWeight=FontWeight.ExtraBold,modifier=Modifier.weight(1f),maxLines=1,overflow=TextOverflow.Ellipsis);IconButton(onClick=onFavorites){Icon(Icons.Default.FavoriteBorder,"Fav